const myosSessionId=myosUuid();
let myosAnalyticsEnabled=()=>localStorage.getItem(MYOS_CONSENT_KEY)==='yes';
function myosAuthToken(){try{const v=JSON.parse(localStorage.getItem(MYOS_AUTH_STORAGE_KEY)||'null');return v?.access_token||null}catch{return null}}
function myosAuthUserId(){try{return JSON.parse(localStorage.getItem(MYOS_AUTH_STORAGE_KEY)||'null')?.user?.id||null}catch{return null}}
function myosSendAnalytics(eventType,appId=null,durationSeconds=0){
 if(!myosAnalyticsEnabled())return;
 const token=myosAuthToken();
 fetch(MYOS_ANALYTICS_URL,{method:'POST',keepalive:true,headers:{'Content-Type':'application/json','apikey':MYOS_ANALYTICS_KEY,'Authorization':'Bearer '+(token||MYOS_ANALYTICS_KEY)},body:JSON.stringify({action:'event',visitorId:myosVisitorId,sessionId:myosSessionId,eventType,appId,durationSeconds})}).catch(()=>{});
}
function myosEnsureConsentNotice(){
 if(!document.body||document.getElementById('myos-analytics-consent'))return;
 if(localStorage.getItem(MYOS_CONSENT_KEY)!==null)return;
 const box=document.createElement('aside');box.id='myos-analytics-consent';
 box.style.cssText='position:fixed;right:18px;bottom:18px;z-index:100000;max-width:360px;padding:16px;border:1px solid #ffffff30;border-radius:16px;background:#17191f;color:#f5f5f5;box-shadow:0 12px 40px #0008;font:13px/1.5 system-ui';
 box.innerHTML='<b style="display:block;font-size:14px;margin-bottom:5px">Anonymous usage analytics</b><span style="color:#c5c8d0">My OS can share anonymous counts of sessions, app launches, and time spent in apps. No message content, passwords, or names are collected. You can decline.</span><div style="display:flex;gap:8px;margin-top:12px"><button data-choice="yes" style="border:0;border-radius:9px;padding:8px 12px;background:#16a34a;color:white;font-weight:700">Allow analytics</button><button data-choice="no" style="border:1px solid #ffffff40;border-radius:9px;padding:8px 12px;background:transparent;color:white">Not now</button></div>';
 box.addEventListener('click',e=>{const choice=e.target.closest('[data-choice]')?.dataset.choice;if(!choice)return;localStorage.setItem(MYOS_CONSENT_KEY,choice);box.remove();if(choice==='yes'){myosSessionAt=Date.now();if(myosActiveApp)myosActiveAppAt=Date.now();myosSendAnalytics('session_start');}});
 document.body.appendChild(box);
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',myosEnsureConsentNotice,{once:true});else myosEnsureConsentNotice();
if(myosAnalyticsEnabled())myosSendAnalytics('session_start');
let myosActiveApp=null,myosActiveAppAt=0,myosSessionAt=Date.now();
function myosFlushAppTime(){if(!myosActiveApp||!myosActiveAppAt)return;const seconds=Math.floor((Date.now()-myosActiveAppAt)/1000);myosActiveAppAt=Date.now();if(seconds>0)myosSendAnalytics('app_time',myosActiveApp,Math.min(seconds,3600))}
function myosSetActiveApp(id){if(myosActiveApp===id){if(myosActiveApp&&!myosActiveAppAt&&document.visibilityState!=='hidden')myosActiveAppAt=Date.now();return}myosFlushAppTime();myosActiveApp=id||null;myosActiveAppAt=myosActiveApp&&document.visibilityState!=='hidden'?Date.now():0}
setInterval(()=>{if(document.visibilityState==='hidden'||!myosAnalyticsEnabled())return;if(myosActiveApp)myosFlushAppTime();const seconds=Math.floor((Date.now()-myosSessionAt)/1000);if(seconds>=30){myosSessionAt=Date.now();myosSendAnalytics('session_time',null,Math.min(seconds,3600));}},30000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){myosFlushAppTime();myosActiveAppAt=0;const seconds=Math.floor((Date.now()-myosSessionAt)/1000);if(seconds>0)myosSendAnalytics('session_time',null,Math.min(seconds,3600));myosSessionAt=Date.now()}else{const active=document.querySelector('.window.active:not(.minimized)');myosSetActiveApp(active?.dataset.app||null);myosSessionAt=Date.now()}});
window.addEventListener('pagehide',()=>{myosFlushAppTime();const seconds=Math.floor((Date.now()-myosSessionAt)/1000);if(seconds>0)myosSendAnalytics('session_time',null,Math.min(seconds,3600));myosSendAnalytics('session_end')});
let myosLastAuthUserId=myosAuthUserId();
window.addEventListener('storage',e=>{if(e.key!==MYOS_AUTH_STORAGE_KEY)return;const next=myosAuthUserId();if(next&&next!==myosLastAuthUserId)myosSendAnalytics('login');myosLastAuthUserId=next});
function activityData(){try{const a=JSON.parse(localStorage.getItem(ACTIVITY_KEY)||'[]');return Array.isArray(a)?a:[]}catch{return []}}
function recordActivity(type,app){const a=activityData();a.push({type,app:app||'desktop',at:Date.now()});const cutoff=Date.now()-90*86400000;localStorage.setItem(ACTIVITY_KEY,JSON.stringify(a.filter(x=>x.at>cutoff).slice(-5000)));if(type==='app'||type==='app_open')myosSendAnalytics('app_open',app||'desktop');else if(type==='session')myosSendAnalytics('session_start')}
async function mountActivityTracker(root){
 let period='day',busy=false;
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const duration=n=>{n=Math.max(0,Math.round(Number(n)||0));if(n<60)return n+'s';if(n<3600)return Math.floor(n/60)+'m '+(n%60)+'s';const h=Math.floor(n/3600),m=Math.floor(n%3600/60);return h+'h '+m+'m'};
 const renderShell=()=>{root.innerHTML='<style>.at{height:100%;overflow:auto;padding:20px;color:var(--text);font:13px system-ui}.at :where(*){color:var(--text)!important}.at-head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:16px}.at h2{font-size:23px;margin:0}.at-muted{color:var(--muted,#9298a8)}.at-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.at-card{padding:15px;border:1px solid #8884;border-radius:15px;background:var(--glass,#8881);min-width:0}.at-value{font-size:25px;font-weight:750;margin-top:7px;font-variant-numeric:tabular-nums}.at-controls{display:flex;gap:7px;flex-wrap:wrap}.at button{border:1px solid #8886;border-radius:9px;padding:8px 11px;background:transparent;color:inherit;cursor:pointer}.at button.active{background:var(--accent,#888);color:white;border-color:transparent}.at-chart{height:175px;display:flex;align-items:end;gap:7px;padding:14px 2px 0}.at-bar-wrap{flex:1;min-width:0;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:end;gap:6px}.at-bar{width:100%;max-width:34px;min-height:2px;border-radius:6px 6px 2px 2px;background:var(--accent,#888);position:relative}.at-bar:hover:after{content:attr(data-tip);position:absolute;bottom:calc(100% + 4px);left:50%;transform:translateX(-50%);white-space:nowrap;background:#171923;color:#fff;padding:4px 6px;border-radius:5px;font-size:10px;z-index:2}.at-day{font-size:10px;color:var(--muted,#9298a8);white-space:nowrap}.at-row{display:grid;grid-template-columns:minmax(80px,1fr) minmax(70px,2fr) auto auto;gap:10px;align-items:center;margin:13px 0}.at-track{height:9px;border-radius:99px;background:#8882;overflow:hidden}.at-fill{height:100%;background:var(--accent,#888);border-radius:99px}.at-table{width:100%;border-collapse:collapse;margin-top:10px}.at-table th,.at-table td{text-align:left;padding:10px 7px;border-bottom:1px solid #8883}.at-table th{color:var(--muted,#9298a8);font-weight:600}.at-note{margin-top:14px;padding:12px;border-radius:11px;background:#8881;color:var(--muted,#9298a8);line-height:1.5}.at-status{margin:12px 0;color:var(--muted,#9298a8)}@media(max-width:700px){.at-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.at{padding:13px}.at-row{grid-template-columns:80px 1fr auto}.at-row .at-people{display:none}.at-table{font-size:11px}.at-table th,.at-table td{padding:8px 4px}}</style><div class="at"><div class="at-head"><div><h2>Activity Tracker</h2><small class="at-muted">Global My OS usage analytics</small></div><div class="at-controls"><button data-period="day" class="active">Daily</button><button data-period="month">Monthly</button><button data-period="all">All time</button><button id="at-refresh">↻ Refresh</button></div></div><div id="at-status" class="at-status">Loading shared analytics…</div><div id="at-content"></div><div class="at-note">Anonymous analytics only: unique visitors, session counts, app launches, and time spent in apps. No message content, passwords, or names are collected. Tracking starts when a visitor allows analytics; older activity cannot be reconstructed. Dashboard access is limited to the signed-in OS owner.</div></div>';};
 const load=async()=>{if(busy)return;busy=true;const status=root.querySelector('#at-status'),content=root.querySelector('#at-content');status.textContent='Loading global activity…';content.innerHTML='';try{const token=myosAuthToken();if(!token)throw new Error('Sign in to Ixxl Chat with the OS owner account to view global analytics.');const res=await fetch(MYOS_ANALYTICS_URL,{method:'POST',headers:{'Content-Type':'application/json','apikey':MYOS_ANALYTICS_KEY,'Authorization':'Bearer '+token},body:JSON.stringify({action:'summary',period})});const data=await res.json();if(!res.ok)throw new Error(data.error||'Analytics could not be loaded.');const t=data.totals||{},trend=data.trend||[],apps=data.apps||[],max=Math.max(1,...trend.map(x=>period==='day'?x.sessions:period==='month'?x.sessions:x.seconds));const bars=trend.map(x=>{const v=period==='all'?x.seconds:x.sessions;const label=period==='day'?x.bucket.slice(5):x.bucket;return '<div class="at-bar-wrap"><div class="at-bar" data-tip="'+esc(period==='all'?duration(v):v+' sessions')+'" style="height:'+Math.max(2,v/max*100)+'%"></div><span class="at-day">'+esc(label)+'</span></div>'}).join('');const rows=apps.map((a,i)=>{const name=allApps().find(x=>x[0]===a.appId)?.[2]||a.appId;const width=Math.max(2,a.seconds/Math.max(1,...apps.map(x=>x.seconds))*100);return '<tr><td>'+esc(name)+'</td><td>'+a.uniqueVisitors.toLocaleString()+'</td><td>'+a.opens.toLocaleString()+'</td><td>'+duration(a.seconds)+'</td><td>'+duration(a.averageSecondsPerOpen)+'</td></tr>'}).join('');const since=data.trackingSince?new Date(data.trackingSince).toLocaleString(): 'Waiting for first visitor';content.innerHTML='<div class="at-grid"><div class="at-card"><small class="at-muted">Unique visitors</small><div class="at-value">'+(t.uniqueVisitors||0).toLocaleString()+'</div></div><div class="at-card"><small class="at-muted">Sessions</small><div class="at-value">'+(t.sessions||0).toLocaleString()+'</div></div><div class="at-card"><small class="at-muted">Sign-ins observed</small><div class="at-value">'+(t.logins||0).toLocaleString()+'</div></div><div class="at-card"><small class="at-muted">App launches</small><div class="at-value">'+(t.appOpens||0).toLocaleString()+'</div></div><div class="at-card"><small class="at-muted">Time in apps</small><div class="at-value">'+duration(t.appSeconds)+'</div></div><div class="at-card"><small class="at-muted">Session time</small><div class="at-value">'+duration(t.sessionSeconds)+'</div></div><div class="at-card"><small class="at-muted">Most-used app</small><div class="at-value" style="font-size:18px">'+esc(apps[0]?(allApps().find(x=>x[0]===apps[0].appId)?.[2]||apps[0].appId):'—')+'</div></div><div class="at-card"><small class="at-muted">Tracking since</small><div class="at-value" style="font-size:15px">'+esc(since)+'</div></div></div><div class="at-card" style="margin-top:12px"><b>'+ (period==='day'?'Daily sessions · last 14 days':period==='month'?'Monthly sessions · last 12 months':'All-time usage · monthly')+'</b><div class="at-chart">'+(bars||'<span class="at-muted">No activity yet</span>')+'</div></div><div class="at-card" style="margin-top:12px"><b>App usage breakdown</b><table class="at-table"><thead><tr><th>App</th><th>People</th><th>Opens</th><th>Total time</th><th>Avg / open</th></tr></thead><tbody>'+(rows||'<tr><td colspan="5" class="at-muted">No app usage has been recorded yet.</td></tr>')+'</tbody></table></div>';status.textContent='Global data · '+(period==='day'?'last 14 days':period==='month'?'last 12 months':'all recorded time')+' · refreshed '+new Date().toLocaleTimeString();}catch(err){status.textContent=err.message||'Could not load analytics.';content.innerHTML='<div class="at-card"><b>Global analytics unavailable</b><p class="at-muted">Make sure you are signed in to Ixxl Chat with the OS owner account. Visitor analytics will appear here after people allow anonymous analytics and use My OS.</p></div>'}finally{busy=false}};
 renderShell();root.querySelectorAll('[data-period]').forEach(btn=>btn.onclick=()=>{period=btn.dataset.period;root.querySelectorAll('[data-period]').forEach(x=>x.classList.toggle('active',x===btn));load()});root.querySelector('#at-refresh').onclick=load;await load();
}
